set-variable.value:
#[%dw 2.0
output application/java

// 1. Build the Id condition (if it exists)
var idCondition = if (!isEmpty(vars.cieReferral.account_id)) 
    "CIE_Client_ID__c = '" ++ vars.cieReferral.account_id ++ "'" 
else null

// 2. Build the secondary conditions dynamically, ignoring empty fields
var fallbackList = [
    if (!isEmpty(vars.cieReferral.last_name)) "LastName = '" ++ vars.cieReferral.last_name ++ "'" else null,
    if (!isEmpty(vars.cieReferral.Medi_Cal_CIN)) "Medi_Cal_ID__pc = '" ++ vars.cieReferral.Medi_Cal_CIN ++ "'" else null,
    if (!isEmpty(vars.cieReferral.birthdate)) "PersonBirthdate = " ++ (vars.cieReferral.birthdate replace "Z" with "") else null
] filter ($ != null)

// 3. Wrap the secondary conditions in parentheses and join them with AND (if any exist)
var fallbackGroup = if (sizeOf(fallbackList) > 0) 
    "(" ++ (fallbackList joinBy " AND ") ++ ")" 
else null

// 4. Combine the Id condition and the secondary group with OR
var finalConditions = [idCondition, fallbackGroup] filter ($ != null) joinBy " OR "

---
// Append to the base query
if (!isEmpty(finalConditions)) 
    "SELECT Id FROM Account WHERE " ++ finalConditions
else 
    "SELECT Id FROM Account LIMIT 0" // Safe fallback if all variables are completely empty]
